// Builds against UNMODIFIED pinned libvgcode ColorRange.cpp and Types.cpp.
// Scalar bin / commanded-flow arithmetic follows the pinned source operations.
#include "ColorRange.hpp"
#include <cmath>
#include <iomanip>
#include <iostream>
namespace libvgcode { class ViewerImpl { public:static void update(ColorRange&r,float v){r.update(v);} }; }
float bin(float value){constexpr float scale[]={100.f,1000.f,10000.f,100000.f,1000000.f},inv[]={.01f,.001f,.0001f,.00001f,.000001f},threshold[]={.095f,.0095f,.00095f,.000095f,.0000095f};int i=0;for(;value<threshold[i]&&i<4;i++);double a=value*scale[i];return int64_t(floor(a+.5))*inv[i];}
int main(){using namespace libvgcode;std::cout<<std::setprecision(9)<<"{\"colors\":[";bool first=true;for(const std::vector<float>&values:std::vector<std::vector<float>>{{.2f},{.2f,.4f},{.2f,.4f,.3f},{0,1,2,3,4},{.00001f,.000025f,.0001f}}){ColorRange range;for(float v:values)ViewerImpl::update(range,v);for(float fraction:std::vector<float>{-.1f,0,.025f,.1f,.2f,.3333f,.5f,.725f,1,1.1f}){float value=range.get_range()[0]+fraction*(range.get_range()[1]-range.get_range()[0]);Color color=range.get_color_at(value);if(!first)std::cout<<',';first=false;std::cout<<"{\"values\":[";for(int i=0;i<values.size();i++){if(i)std::cout<<',';std::cout<<values[i];}std::cout<<"],\"value\":"<<value<<",\"rgb\":["<<int(color[0])<<','<<int(color[1])<<','<<int(color[2])<<"],\"legend\":[";auto legend=range.get_values();for(int i=0;i<legend.size();i++){if(i)std::cout<<',';std::cout<<legend[i];}std::cout<<"]}";}}
std::cout<<"],\"bins\":[";first=true;for(float value:{0.f,.000001f,.00000949f,.0000095f,.00009499f,.000095f,.0009499f,.00095f,.009499f,.0095f,.09499f,.095f,.123456f,1.345f,10.567f,250.333f}){if(!first)std::cout<<',';first=false;std::cout<<'['<<value<<','<<bin(value)<<']';}
std::cout<<"],\"flows\":[";first=true;for(const std::array<float,6>&v:std::vector<std::array<float,6>>{{10,0,0,1,1.75,1200},{3,4,.2,.213,1.75,4000},{.001,.003,.2,.0093,2.85,3578},{-12.341,7.897,0,.759,1.75,124.91},{1000,1000,1000,.0001,1.75,45000},{.4,.04,0,.03333,1.75,600}}){float radius=.5f*v[4],area=float(M_PI)*(radius*radius),length=std::sqrt(double(v[0])*v[0]+double(v[1])*v[1]+double(v[2])*v[2]),volume=area*double(v[3]),per_mm=volume/length,speed=double(v[5])*(1.f/60.f),flow=speed*per_mm;if(!first)std::cout<<',';first=false;std::cout<<"{\"input\":[";for(int i=0;i<6;i++){if(i)std::cout<<',';std::cout<<v[i];}std::cout<<"],\"flow\":"<<flow<<",\"mm3PerMm\":"<<per_mm<<'}';}std::cout<<"]}\n";}
